/** Protocol artefacts: CAP 1.2 XML generated by the backend (validated against the XSD there) and the FHIR bundle of the 119 simulator inbox. */
import { buildCapJson } from "../lib/cap";
import { fetchText, loadSimInbox, num, postJson, rec, str } from "./api";

export interface Artefact {
  kind: "cap" | "fhir";
  name: string;
  mime: string;
  ext: "xml" | "json";
  /** exact text of the document (bytes = UTF-8 encoding of this string) */
  content: string;
  /** From the API only; null when the API did not say. */
  validated: boolean | null;
  generationMs: number | null;
  sha256: string | null;
}

export async function sha256Hex(text: string): Promise<string | null> {
  if (typeof crypto === "undefined" || crypto.subtle === undefined) return null;
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

const genMsOf = (j: Record<string, unknown> | null): number | null => (j === null ? null : num(j.generation_ms) ?? num(j.gen_ms));

export interface CapRequest { identifier: string; event: string; headline: string; description: string; instruction: string; areaDesc: string; lat: number; lon: number; bitLines?: string[] }

/** POST /cap/alerts (server validates against the OASIS CAP 1.2 XSD), then read back the stored XML. Exercise status only. */
export async function generateCap(r: CapRequest, now: Date = new Date()): Promise<Artefact> {
  const cap = buildCapJson({ identifier: r.identifier, sent: now, event: r.event, headline: r.headline, description: r.description, instruction: r.instruction, areaDesc: r.areaDesc, lat: r.lat, lon: r.lon });
  const res = await postJson("/cap/alerts", { cap, ...(r.bitLines === undefined ? {} : { bit_lines: r.bitLines }) });
  const j = rec(res.json);
  if (res.status !== 201 || j === null) throw new Error(`CAP 생성 거부 ${res.status}`);
  const url = str(j.xml_url);
  if (url === null) throw new Error("CAP 응답에 xml_url 없음");
  const xml = await fetchText(url);
  return { kind: "cap", name: `${r.identifier}.xml`, mime: "application/xml", ext: "xml", content: xml, validated: typeof j.xsd_valid === "boolean" ? j.xsd_valid : null, generationMs: genMsOf(j), sha256: await sha256Hex(xml) };
}

/** POST /twin/{sgg}/actions/{id}/cap : the backend builds, XSD-validates and returns the XML with its measured generation_ms. */
export async function generateActionCap(capUrl: string, name: string): Promise<Artefact> {
  const res = await postJson(capUrl, {});
  const j = rec(res.json);
  const xml = str(j?.xml);
  if (res.status >= 300 || j === null || xml === null) throw new Error(`CAP 생성 거부 ${res.status}`);
  return { kind: "cap", name: `${str(j.identifier) ?? name}.xml`, mime: "application/xml", ext: "xml", content: xml, validated: typeof j.xsd_valid === "boolean" ? j.xsd_valid : null, generationMs: genMsOf(j), sha256: await sha256Hex(xml) };
}

/** Read the CAP an agent run stored. */
export async function readCap(id: string, xmlUrl: string, xsdValid: boolean | null): Promise<Artefact> {
  const xml = await fetchText(xmlUrl);
  return { kind: "cap", name: `${id}.xml`, mime: "application/xml", ext: "xml", content: xml, validated: xsdValid, generationMs: null, sha256: await sha256Hex(xml) };
}

/** The FHIR R4 Bundle the agent put into the 119 simulator inbox (payload.fhir). */
export async function readFhir(receiptId: string): Promise<Artefact | null> {
  const inbox = rec(await loadSimInbox(receiptId));
  const fhir = rec(rec(inbox?.payload)?.fhir);
  if (fhir === null) return null;
  const content = JSON.stringify(fhir, null, 2);
  return { kind: "fhir", name: `${str(fhir.id) ?? receiptId}.json`, mime: "application/json", ext: "json", content, validated: null, generationMs: genMsOf(inbox), sha256: await sha256Hex(content) };
}

/** Download the exact bytes of the artefact. */
export function saveArtefact(a: Artefact): void {
  const url = URL.createObjectURL(new Blob([a.content], { type: `${a.mime};charset=utf-8` }));
  const link = document.createElement("a");
  link.href = url;
  link.download = a.name;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

export { clockKst as clock } from "./clock";
export const short = (h: string | null): string => (h === null ? "" : `sha256 ${h.slice(0, 4)}…`);
